from pysat.solvers import Glucose3
from itertools import combinations
n=12; L=22
edges=[]
for g in range(4):
    for i in range(3):
        for j in range(i+1,3):
            edges.append((3*g+i,3*g+j))
for g in range(3):
    for i in range(3):
        edges.append((3*g+i,3*(g+1)+i))
print('edges',len(edges),edges)
vid={}
counter=1
# x(v,l)
def x(v,l):
    global counter
    key=('x',v,l)
    if key not in vid:
        vid[key]=len(vid)+1
    return vid[key]
def y(e,d): # d 1..21
    key=('y',e,d)
    if key not in vid:
        vid[key]=len(vid)+1
    return vid[key]
solver=Glucose3()
# vertex exactly one
for v in range(n):
    solver.add_clause([x(v,l) for l in range(L)])
    for a,b in combinations(range(L),2): solver.add_clause([-x(v,a),-x(v,b)])
# label at most once
for l in range(L):
    for u,v in combinations(range(n),2): solver.add_clause([-x(u,l),-x(v,l)])
# edge exactly one diff
for e in range(len(edges)):
    solver.add_clause([y(e,d) for d in range(1,L)])
    for a,b in combinations(range(1,L),2): solver.add_clause([-y(e,a),-y(e,b)])
# diff at most one edge
for d in range(1,L):
    for e1,e2 in combinations(range(len(edges)),2): solver.add_clause([-y(e1,d),-y(e2,d)])
# implications endpoint labels -> diff y. disallow same label already global
for e,(u,v) in enumerate(edges):
    for a in range(L):
        for b in range(L):
            if a==b: continue
            solver.add_clause([-x(u,a),-x(v,b), y(e,abs(a-b))])
# symmetry: x0 < complement maybe label v0 <=10: forbid >10
# Not necessary but can add maybe.
#for l in range(11,22): solver.add_clause([-x(0,l)])
print('vars',len(vid),'clauses',solver.nof_clauses())
res=solver.solve()
print('sat',res)
if res:
    model=set(lit for lit in solver.get_model() if lit>0)
    sol=[]
    for v in range(n):
        lab=[l for l in range(L) if x(v,l) in model]
        sol.append(lab[0])
    print(sol)
    diffs=[abs(sol[u]-sol[v]) for u,v in edges]
    print(sorted(diffs),len(set(diffs)),diffs)
    for i,e in enumerate(edges): print(i,e,diffs[i])
